n=A.au(0,"L3-06",3,A.a([A.f("A push above the distribution range to sweep liquidity before reversing down","C\xfa \u0111\u1ea9y gi\xe1 l\xean tr\xean v\xf9ng ph\xe2n ph\u1ed1i \u0111\u1ec3 qu\xe9t thanh kho\u1ea3n tr\u01b0\u1edbc khi \u0111\u1ea3o chi\u1ec1u gi\u1ea3m","\u7a81\u7834\u6d3e\u53d1\u533a\u95f4\u4ee5\u626b\u8361\u6d41\u52a8\u6027\uff0c\u968f\u540e\u53cd\u8f6c\u4e0b\u8dcc","\u53cd\u8ee2\u4e0b\u964d\u524d\u306b\u5206\u6563\u5e2f\u306e\u4e0a\u306b\u62bc\u3057\u4e0a\u3052\u3066\u6d41\u52d5\u6027\u3092\u72e9\u308b\u3053\u3068","\ubc18\uc804 \ud558\ub77d \uc804, \ubd84\uc0b0 \uad6c\uac04 \uc704\ub85c \ubc00\uc5b4\uc62c\ub824 \uc720\ub3d9\uc131\uc744 \uc4f8\uc5b4\uac00\ub294 \uac83"),A.f("A stable accumulation phase","Giai \u0111o\u1ea1n t\xedch lu\u1ef9 \u1ed5n \u0111\u1ecbnh","\u7a33\u5b9a\u7684\u5438\u7b79\u9636\u6bb5","\u5b89\u5b9a\u3057\u305f\u8cb7\u3044\u96c6\u3081\u6bb5\u968e","\uc548\uc815\uc801\uc778 \ub9e4\uc9d1 \ub2e8\uacc4"),A.f("An advanced RSI indicator","M\u1ed9t ch\u1ec9 b\xe1o \u0111o RSI n\xe2ng cao","\u4e00\u79cd\u9ad8\u7ea7RSI\u6307\u6807","\u9ad8\u5ea6\u306aRSI\u6307\u6a19","\uace0\uae09 RSI \uc9c0\ud45c"),A.f("Another name for Stop Loss","T\xean g\u1ecdi kh\xe1c c\u1ee7a Stop Loss","\u6b62\u635f\u7684\u53e6\u4e00\u79cd\u8bf4\u6cd5","\u640d\u5207\u308a\u306e\u5225\u306e\u8a00\u3044\u65b9","\uc190\uc808\ub9e4\uc758 \ub2e4\ub978 \ud45c\ud604")],e6),m,n)
